exercises.solution:
function lcm(nums) {
  function gcd(a, b) {
    while (b !== 0) [a, b] = [b, a % b];
    return a;
  }
  function lcmTwo(a, b) {
    return (a / gcd(a, b)) * b;
  }
  return nums.reduce((acc, n) => lcmTwo(acc, n));
}

