(code) => {
  const fn = new Function(code + '; return chineseRemainder;')();
  const results = [];
  results.push({ pass: fn([2,3,2], [3,5,7]) === 23, description: 'x≡2(mod3), x≡3(mod5), x≡2(mod7) → 23', got: String(fn([2,3,2], [3,5,7])) });
  results.push({ pass: fn([1,2], [3,6]) === -1, description: 'Coprime check: [3,6] returns -1', got: String(fn([1,2], [3,6])) });
  results.push({ pass: fn([0,3,4], [3,4,5]) === 39, description: 'x≡0(mod3), x≡3(mod4), x≡4(mod5) → 39', got: String(fn([0,3,4], [3,4,5])) });
  results.push({ pass: fn([1], [5]) === 1, description: 'Single congruence: x≡1(mod5) → 1', got: String(fn([1], [5])) });
  const r = fn([2,3,1], [3,5,7]);
  results.push({ pass: r % 3 === 2 && r % 5 === 3 && r % 7 === 1, description: 'Result satisfies all 3 congruences', got: String(r) });
  results.push({ pass: fn([0,0,0], [3,5,7]) === 0, description: 'All zero remainders → 0', got: String(fn([0,0,0], [3,5,7])) });
  return results;
}

