exercises.solution:
function normalDist(x, mean, stdDev) {
  // PDF
  const exp = Math.exp(-((x - mean) ** 2) / (2 * stdDev ** 2));
  const pdf = (1 / (stdDev * Math.sqrt(2 * Math.PI))) * exp;

  // CDF using error function approximation
  const z = (x - mean) / (stdDev * Math.sqrt(2));
  const a1 = 0.254829592, a2 = -0.284496736, a3 = 1.421413741;
  const a4 = -1.453152027, a5 = 1.061405429, p = 0.3275911;
  const sign = z < 0 ? -1 : 1;
  const absZ = Math.abs(z);
  const t = 1 / (1 + p * absZ);
  const erf = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-(absZ * absZ));
  const cdf = 0.5 * (1 + sign * erf);

  return {
    pdf: Math.round(pdf * 1000000) / 1000000,
    cdf: Math.round(cdf * 10000) / 10000
  };
}

